export declare const otpTemplate = "\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>V\u00E9rification %societe%</title>\n  <style>\n      body {\n          font-family: Arial, sans-serif;\n          background: #f5f7fa;\n          margin: 0;\n          padding: 0;\n      }\n      .container {\n          max-width: 480px;\n          margin: 40px auto;\n          background: #ffffff;\n          border: 1px solid #e0e0e0;\n          border-radius: 8px;\n          padding: 24px;\n          text-align: center;\n      }\n      .header {\n          font-size: 22px;\n          font-weight: bold;\n          color: #333;\n          margin-bottom: 12px;\n      }\n      .otp-box {\n          font-size: 32px;\n          font-weight: bold;\n          letter-spacing: 10px;\n          color: #2c3e50;\n          background: #f0f0f0;\n          padding: 16px;\n          border-radius: 6px;\n          margin: 20px 0;\n      }\n      .info {\n          font-size: 14px;\n          color: #555;\n          margin-top: 10px;\n      }\n      .footer {\n          font-size: 12px;\n          color: #888;\n          margin-top: 24px;\n      }\n  </style>\n</head>\n<body>\n<div class=\"container\">\n  <div class=\"header\">V\u00E9rification %societe%</div>\n  <p>Bonjour <strong>%email%</strong>,</p>\n  <p>Veuillez utiliser le code \u00E0 usage unique (OTP) suivant pour v\u00E9rifier votre compte :</p>\n  <div class=\"otp-box\">%otp%</div>\n  <p class=\"info\">Ce code est valable pendant 10 minutes. Ne le partagez avec personne.</p>\n  <div class=\"footer\">\n    Envoy\u00E9 par %societe% le %date%\n  </div>\n</div>\n</body>\n</html>\n";
